{
  "root_cause": "The Drawer component's _getShowOptions returns modal: true for side drawers (due to backdrop: true default), causing showModal() to be used instead of show(). This centers the dialog natively, conflicts with side-drawer CSS positioning, and fails to trap focus in the side-positioned drawer, leaving focus on the trigger button. Additionally, DialogBase does not enforce focus when a drawer/dialog is shown, and does not store the relatedTarget to restore focus when closed via Escape.",
  "repair_strategy": "1. Change Drawer._getShowOptions to always return modal: false for side drawers, so show() is used and _enforceFocus (in DialogBase._showElement) explicitly focuses the first focusable element (autofocus or close button). 2. Add _relatedTarget property to DialogBase to track the triggering element. 3. In _show, store relatedTarget. 4. Add _enforceFocus method to move focus to the first focusable/autofocus element. 5. In _showElement, call _enforceFocus() after showing the dialog. 6. In _closeAndCleanup, restore focus to _relatedTarget if visible, then clear it. 7. Import isVisible utility.",
  "edits": [
    {
      "path": "js/src/drawer.ts",
      "sha256": "ec1263ee997c9acf245a67902c7e977f7550be6b313ada12b594925efa11847a",
      "before": "  protected override _getShowOptions(): { modal: boolean, preventBodyScroll: boolean } {
    const useModal = Boolean(this._config.backdrop) || !this._config.scroll
    return {
      modal: useModal,
      preventBodyScroll: !this._config.scroll
    }
  }",
      "after": "  protected override _getShowOptions(): { modal: boolean, preventBodyScroll: boolean } {
    return {
      modal: false,
      preventBodyScroll: !this._config.scroll
    }
  }"
    },
    {
      "path": "js/src/dialog-base.ts",
      "sha256": "365b3e69778c2fdc18db529770b50c1881f0588747bead1c79c46c86f9ca9f1b",
      "before": "import BaseComponent from './base-component.js'
import Data from './dom/data.js'
import EventHandler, { type BootstrapEvent } from './dom/event-handler.js'
import SelectorEngine from './dom/selector-engine.js'",
      "after": "import BaseComponent from './base-component.js'
import Data from './dom/data.js'
import EventHandler, { type BootstrapEvent } from './dom/event-handler.js'
import SelectorEngine from './dom/selector-engine.js'
import { isVisible } from '../util/index.js'"
    },
    {
      "path": "js/src/dialog-base.ts",
      "sha256": "365b3e69778c2fdc18db529770b50c1881f0588747bead1c79c46c86f9ca9f1b",
      "before": "class DialogBase extends BaseComponent {
  protected declare _element: HTMLDialogElement
  protected declare _config: DialogBaseConfig
  protected declare _isTransitioning: boolean
  protected declare _openedAsModal: boolean
  protected declare _cancelHandler: (event: BootstrapEvent) => void",
      "after": "class DialogBase extends BaseComponent {
  protected declare _element: HTMLDialogElement
  protected declare _config: DialogBaseConfig
  protected declare _isTransitioning: boolean
  protected declare _openedAsModal: boolean
  protected declare _cancelHandler: (event: BootstrapEvent) => void
  protected declare _relatedTarget: HTMLElement | null"
    },
    {
      "path": "js/src/dialog-base.ts",
      "sha256": "365b3e69778c2fdc18db529770b50c1881f0588747bead1c79c46c86f9ca9f1b",
      "before": "  protected async _show(relatedTarget?: HTMLElement): Promise<void> {
    this._isTransitioning = true
    this._onBeforeShow()

    const { modal, preventBodyScroll } = this._getShowOptions()
    this._showElement({ modal, preventBodyScroll })

    await this._queueCallback(() => {
      this._isTransitioning = false
      EventHandler.trigger(
        this._element,
        this.constructor.eventName('shown'),
        { relatedTarget }
      )
    }, this._element, this._isAnimated())
  }",
      "after": "  protected async _show(relatedTarget?: HTMLElement): Promise<void> {
    this._relatedTarget = relatedTarget || null
    this._isTransitioning = true
    this._onBeforeShow()

    const { modal, preventBodyScroll } = this._getShowOptions()
    this._showElement({ modal, preventBodyScroll })

    await this._queueCallback(() => {
      this._isTransitioning = false
      EventHandler.trigger(
        this._element,
        this.constructor.eventName('shown'),
        { relatedTarget }
      )
    }, this._element, this._isAnimated())
  }"
    },
    {
      "path": "js/src/dialog-base.ts",
      "sha256": "365b3e69778c2fdc18db529770b50c1881f0588747bead1c79c46c86f9ca9f1b",
      "before": "  protected _showElement({ modal = true, preventBodyScroll = true }: { modal?: boolean, preventBodyScroll?: boolean } = {}): void {
    this._openedAsModal = modal

    if (modal) {
      this._element.showModal()
    } else {
      this._element.show()
    }

    if (preventBodyScroll) {
      // Lock scroll on the root element (not <body>) so it lands on the same
      // element that carries `scrollbar-gutter: stable`. Co-locating them keeps
      // the gutter reserved while the scrollbar is hidden, so the page doesn't
      // shift (and the ::backdrop covers the gutter instead of leaving a strip).
      document.documentElement.classList.add(CLASS_NAME_OPEN)
    }
  }",
      "after": "  protected _showElement({ modal = true, preventBodyScroll = true }: { modal?: boolean, preventBodyScroll?: boolean } = {}): void {
    this._openedAsModal = modal

    if (modal) {
      this._element.showModal()
    } else {
      this._element.show()
    }

    // Move focus into the dialog
    this._enforceFocus()

    if (preventBodyScroll) {
      // Lock scroll on the root element (not <body>) so it lands on the same
      // element that carries `scrollbar-gutter: stable`. Co-locating them keeps
      // the gutter reserved while the scrollbar is hidden, so the page doesn't
      // shift (and the ::backdrop covers the gutter instead of leaving a strip).
      document.documentElement.classList.add(CLASS_NAME_OPEN)
    }
  }"
    },
    {
      "path": "js/src/dialog-base.ts",
      "sha256": "365b3e69778c2fdc18db529770b50c1881f0588747bead1c79c46c86f9ca9f1b",
      "before": "  protected _closeAndCleanup(): void {
    this._element.close()
    this._openedAsModal = false

    // Only restore scroll if no other modal dialogs are open
    if (!document.querySelector('dialog[open]:modal')) {
      document.documentElement.classList.remove(CLASS_NAME_OPEN)
    }
  }",
      "after": "  protected _closeAndCleanup(): void {
    this._element.close()
    this._openedAsModal = false

    // Only restore scroll if no other modal dialogs are open
    if (!document.querySelector('dialog[open]:modal')) {
      document.documentElement.classList.remove(CLASS_NAME_OPEN)
    }

    // Restore focus to the element that opened the dialog
    if (this._relatedTarget && isVisible(this._relatedTarget)) {
      this._relatedTarget.focus({ preventScroll: true })
    }
    this._relatedTarget = null
  }"
    },
    {
      "path": "js/src/dialog-base.ts",
      "sha256": "365b3e69778c2fdc18db529770b50c1881f0588747bead1c79c46c86f9ca9f1b",
      "before": "  protected _onCancel(): void {
    // No-op by default — Dialog overrides to fire cancel event
  }",
      "after": "  protected _onCancel(): void {
    // No-op by default — Dialog overrides to fire cancel event
  }

  protected _enforceFocus(): void {
    // Focus the first focusable element, preferring [autofocus]
    const autofocus = this._element.querySelector('[autofocus]') as HTMLElement | null
    if (autofocus) {
      autofocus.focus({ preventScroll: true })
      return
    }
    const focusable = this._element.querySelector('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])') as HTMLElement | null
    if (focusable) {
      focusable.focus({ preventScroll: true })
    }
  }"
    }
  ],
  "expected_accessibility_effect": "Keyboard users can open Sort and Filters drawers and immediately interact with controls (close button, search input, checkboxes) because focus moves into the drawer on open. Pressing Escape closes the drawer and returns focus to the trigger button, satisfying WCAG 2.1.1, 2.4.3, and 4.1.2.",
  "functional_risks": [
    "Focus restoration in _closeAndCleanup may duplicate the data API's hidden event listener (both target the same element).",
    "The isVisible utility must be correctly imported and available.",
    "If a drawer is opened programmatically without a relatedTarget, focus restoration will be skipped (safe)."
  ],
  "verification_requirements": [
    "Press Enter on #sort-open → Sort drawer opens, focus lands on #sort-close.",
    "Press Escape → Sort drawer closes, focus returns to #sort-open.",
    "Press Enter on #filters-open → Filters drawer opens, focus lands on #filters-search (autofocus).",
    "Tab through Filters drawer controls (search, checkboxes, apply button) works.",
    "Form submission updates #applied text and closes Filters drawer.",
    "Regression guard: click #filters-open, press Escape → drawer closes, focus returns to #filters-open."
  ]
}
